import React from 'react';
import './Home.css';

function Home() {
  return (
    <div className="home">
      <section className="hero">
        <h1>Buy & Sell Two-Wheelers Online</h1>
        <p>Browse latest bikes and scooters from trusted sellers.</p>
        <button>Explore Now</button>
      </section>

      <section className="products">
        <h2>Latest Listings</h2>
        <div className="product-grid">
          <div className="product-card">
            <img src="data:image/jpeg;base64," alt="bike" />
            <h3>Honda MotorBike</h3>
            <p>₹72,000</p>
          </div>
          <div className="product-card">
            <img src="https://via.placeholder.com/200x150" alt="bike" />
            <h3>Yamaha R15 V4</h3>
            <p>₹1,79,000</p>
          </div>
          {/* Add more cards here */}
        </div>
      </section>
    </div>
  );
}

export default Home;
